    storyThroughLine: "Eight personas in three months is a fast clock for a product this conceptually dense. Treating the personas and Kano scoring as the actual filter, rather than scoping by argument, is what made it possible.",
    beats: {
      "decisions-outcomes": [
        { id: "the-project", heading: "The project", body: "Below is a three-month process that started with generative customer discovery\nand ended with a launch in the App Store. I was instrumental in driving clarity\nof scope for a mobile experience for a highly complex product.", media: [] },
        { id: "interviews-synthesized-in-trello", heading: "Interviews synthesized in Trello", body: "I conducted interviews synthesized in Trello to find shared behaviors.", media: [{ kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/02-lobus-screen-shot-2022-02-11-at-5-00-40-pm.jpg", alt: "Interviews synthesized in Trello", width: 2000, height: 1142 }] },
        { id: "personas-and-needs-mapped-to-the-backlog", heading: "Personas and needs mapped to the backlog", body: "I then led the team through the process of mapping personas and needs to our\nbacklog and zero-to-one opportunities. I wrote eight discrete personas complete\nwith high-level jobs-to-be-done and mapped them to industry segments.", media: [{ kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/03-lobus-screen-shot-2022-02-11-at-5-02-58-pm.jpg", alt: "Personas and needs mapped to the backlog, 1 of 2", width: 2000, height: 1123 }, { kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/04-lobus-screen-shot-2022-02-11-at-5-01-32-pm.jpg", alt: "Personas and needs mapped to the backlog, 2 of 2", width: 2000, height: 1124 }] },
        { id: "concepts-scored-with-the-kano-model", heading: "Concepts scored with the Kano model", body: "We tested concepts with a newly created customer council and scored them with\nthe Kano model.", media: [{ kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/05-lobus-screen-shot-2022-02-24-at-3-48-44-pm.jpg", alt: "Concepts scored with the Kano model", width: 2000, height: 1125 }] },
        { id: "concepts-tested-future-state-and-new-brand", heading: "Concepts tested: future state and new brand", body: "", media: [{ kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/06-lobus-iphone-12-pro-gold-shadow-11.jpg", alt: "Concepts tested: future state and new brand, 1 of 10", width: 2000, height: 1293 }, { kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/07-lobus-iphone-12-pro-gold-shadow-9.jpg", alt: "Concepts tested: future state and new brand, 2 of 10", width: 2000, height: 1293 }, { kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/08-lobus-iphone-12-pro-gold-shadow-5.jpg", alt: "Concepts tested: future state and new brand, 3 of 10", width: 2000, height: 1293 }, { kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/09-lobus-iphone-12-pro-gold-shadow-3.jpg", alt: "Concepts tested: future state and new brand, 4 of 10", width: 2000, height: 1293 }, { kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/10-lobus-image-27.jpg", alt: "Concepts tested: future state and new brand, 5 of 10", width: 1695, height: 1081 }, { kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/11-lobus-iphone-12-pro-gold-shadow-10.jpg", alt: "Concepts tested: future state and new brand, 6 of 10", width: 2000, height: 1293 }, { kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/12-lobus-iphone-12-pro-gold-shadow-8.jpg", alt: "Concepts tested: future state and new brand, 7 of 10", width: 2000, height: 1293 }, { kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/13-lobus-iphone-12-pro-gold-shadow-4.jpg", alt: "Concepts tested: future state and new brand, 8 of 10", width: 2000, height: 1293 }, { kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/14-lobus-iphone-12-pro-gold-shadow2.jpg", alt: "Concepts tested: future state and new brand, 9 of 10", width: 2000, height: 1293 }, { kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/15-lobus-image-28.jpg", alt: "Concepts tested: future state and new brand, 10 of 10", width: 1695, height: 1081 }] },
        { id: "the-verified-object-flow", heading: "The Verified Object Flow", body: "The capture flow and collection engagement model is a targeted solution that\nbecame the foundation for capture of physical objects for verification.", media: [{ kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/16-lobus-screen-shot-2022-02-11-at-5-29-21-pm.jpg", alt: "The Verified Object Flow", width: 2000, height: 1129 }] },
        { id: "launch-prototype", heading: "Launch prototype", body: "A revised mobile prototype matching the existing brand.", media: [{ kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/lobus-verified-object-capture/17-lobus-screen-shot-2022-02-12-at-9-50-48-am.jpg", alt: "Launch prototype", width: 2000, height: 1124 }] },
        { id: "outcome", heading: "Outcome", body: "An App Store launch three months after discovery started.", media: [] },
      ],
    },
