    hero: { kind: "image", src: "https://marliin-recipient-worker.brett-6a3.workers.dev/images/youscience-results-platform-redesign/00-ysproduct-hero.jpg", alt: "YouScience Results Platform", width: 1670, height: 960, edgeColors: { left: "#eceff0", right: "#eceff0" } },
